const t = $('When Executed by Another Workflow').first().json;

// Deux echecs distincts aboutissent ici, et les confondre ferait chercher au
// mauvais endroit.
const boutons = String(t.reply_markup ?? '').trim();
const raison = boutons
  ? 'Boutons perdus - appel sans boutique avec reply_markup. Le noeud Telegram'
    + ' de n8n ne sait pas relayer un reply_markup brut : le message serait'
    + ' parti sans ses boutons, et personne ne l aurait vu. Faire passer cet'
    + ' appelant par l API DjiguiFlow en lui transmettant `boutique`.'
  : `Envoi impossible - canal='${t.canal || 'vide'}' destinataire='${t.destinataire || 'vide'}'`;

return [{ json: {
  timestamp: $now.toISO(),
  canal: String(t.canal || ''),
  destinataire: String(t.destinataire || ''),
  message: String(t.message || '').slice(0, 200),
  statut: 'ERREUR',
  erreur: raison.slice(0, 300),
  // Rien n a ete tente : le defaut est dans l appel, pas chez le fournisseur.
  // `Signaler l echec` s en sert pour ne pas ameuter l exploitant.
  origine: 'appelant',
}}];

// Verdict rendu a l appelant.
//
// CE NOEUD NE DOIT JAMAIS LEVER. S il leve, le message est DEJA PARTI, et
// l appelant — qui porte un reessai — rejoue tout le sous-workflow : le
// client recoit deux ou trois fois le meme message. C est arrive le 14 aout.
//
// La cause : la lecture se faisait par `$('Journal possible ?').first()`, qui
// ne lit que la PREMIERE sortie de l aiguillage. Quand l appel n a pas de
// classeur a journaliser, l aiguillage part sur la SECONDE : la premiere est
// vide, `.first()` rend `undefined`, et `.json` plante dessus.
//
// On lit donc les noeuds de journal directement. Un seul s execute par
// chemin ; les autres levent « unexecuted », ce que le try avale.
const JOURNAUX = [
  'Log succès',
  'Log échec',
  'Log succès1',
  'Log échec1',
  'Log envoi invalide',
];

let l = {};
for (const nom of JOURNAUX) {
  try {
    const item = $(nom).first();
    if (item && item.json) { l = item.json; break; }
  } catch (e) {
    // Noeud non emprunte sur ce chemin : c est normal.
  }
}

let t = {};
try {
  t = $('When Executed by Another Workflow').first().json || {};
} catch (e) {
  t = {};
}

const journalTrouve = Object.keys(l).length > 0;
const ok = String(l.statut || '') === 'ok';

// Un destinataire vide n est pas une panne : c est un marchand qui n a pas
// renseigne son Telegram, ou un client sans numero.
const sansDestinataire = !String(t.destinataire == null ? '' : t.destinataire).trim();

// Journal introuvable : on ne sait pas. On classe en « appelant » pour que
// `Signaler l echec` ne leve PAS — un doute ne doit jamais couter un doublon
// chez le client.
return [{ json: {
  ok,
  statut: ok ? 'ok' : 'ERREUR',
  timestamp: String(l.timestamp || ''),
  canal: String(l.canal || t.canal || ''),
  destinataire: String(l.destinataire || t.destinataire || ''),
  message: String(l.message || ''),
  erreur: String(l.erreur || (journalTrouve ? '' : 'journal introuvable')),
  origine: (sansDestinataire || !journalTrouve) ? 'appelant' : String(l.origine || 'fournisseur'),
} }];

// Un envoi rate doit etre bruyant.
//
// Les noeuds d envoi portent `onError: continueErrorOutput` pour que le journal
// soit ecrit quoi qu il arrive. L effet de bord etait qu aucun appelant
// n apprenait jamais l echec, et ils sont quatorze. On leve donc ICI, apres le
// journal : ce sous-workflow declare `Alerte Erreurs` comme workflow d erreur,
// l exploitant est prevenu meme si l appelant choisit de continuer.
//
// L ETRANGLEMENT N EST PLUS ICI, ET N Y A JAMAIS FONCTIONNE. Il prenait la
// forme d une memoire `$getWorkflowStaticData` marquant un `canal|destinataire`
// deja signale dans la journee. Or n8n ne persiste la memoire statique qu au
// terme d une execution REUSSIE — et cette execution-ci se termine justement
// par le `throw` ci-dessous. Le marquage etait donc rejete a chaque passage, et
// le garde-fou ne filtrait rien. Constate le 14 aout : executions 5365, 5367 et
// 5369, meme destinataire, la meme seconde, trois levees.
//
// L etranglement vit desormais dans `Alerte Erreurs`, dont les executions
// reussissent et dont la memoire, elle, tient.
const v = $input.first().json || {};

// `origine: 'appelant'` — ni canal ni destinataire exploitables. C est un
// defaut d appel, deja journalise, et il se repeterait a chaque message d un
// client sans numero : le signaler noierait le canal technique.
if (v.ok === true || v.origine === 'appelant') return [{ json: v }];

// CANAL NON EQUIPE : ce n est pas un incident, c est une configuration.
//
// Un marchand qui n a pas connecte WhatsApp — c est-a-dire tout nouvel inscrit
// — fait echouer en 424 chacun des SEPT workflows qui previennent sur les deux
// canaux : nouvelle commande, resume quotidien, resume hebdo, contenus hebdo,
// alerte stock, dashboard gerant, relance d echeance. A chaque envoi, tous les
// jours. Le canal technique se remplirait de bruit, et le bruit finit par
// masquer les vraies pannes — exactement ce que ce garde-fou existe pour
// eviter.
//
// Le marchand, lui, EST prevenu : son tableau de bord affiche en rouge ce qu il
// n a pas encore branche. C est la que cette information a sa place, pas dans
// une alerte d exploitation.
//
// Meme raisonnement que le `origine: 'appelant'` ci-dessus : deja journalise,
// repetitif, et sans action possible de notre cote.
const texteErreur = String(v.erreur == null ? '' : v.erreur);
if (/ 424 /.test(texteErreur) || /aucun jeton/i.test(texteErreur)) {
  return [{ json: { ...v, signale: false, motif_silence: 'canal non equipe' } }];
}

// Sur une seule ligne et sans deux-points : n8n scinde sinon le texte de
// l Error, et `Alerte Erreurs` n en lit que la seconde moitie.
const assainir = (s) => String(s == null ? '' : s)
  .replace(/[_*`\[\]:]/g, ' ').replace(/\s+/g, ' ').trim();

throw new Error(
  `Message non delivre sur ${assainir(v.canal) || 'canal inconnu'} vers `
  + `${assainir(v.destinataire) || 'destinataire vide'}, cause `
  + assainir(v.erreur || 'sans detail').slice(0, 300),
);
